(async()=>{ window.scrollTo(0,600); await new Promise(r=>setTimeout(r,600));
 var cs=getComputedStyle(document.documentElement).getPropertyValue('--ps-virsus');
 var b=document.querySelector('.pskat-bar'); var th=document.querySelector('.pskat-lent-lauk .pskat-t thead th');
 var lauk=document.querySelector('.pskat-lent-lauk'); var lcs=lauk?getComputedStyle(lauk):null;
 return {virsus:cs, scrollY:window.scrollY, scrollX:window.scrollX,
  bar: b?{top:Math.round(b.getBoundingClientRect().top),bottom:Math.round(b.getBoundingClientRect().bottom),pos:getComputedStyle(b).position}:null,
  thead: th?{top:Math.round(th.getBoundingClientRect().top),pos:getComputedStyle(th).position,cssTop:getComputedStyle(th).top}:null,
  lauk: lauk?{ovx:lcs.overflowX,ovy:lcs.overflowY,scrollH:lauk.scrollHeight,clientH:lauk.clientHeight,rectTop:Math.round(lauk.getBoundingClientRect().top)}:null,
  docScroll: document.scrollingElement===document.documentElement?'html':'kitas',
  wpwrapOv: getComputedStyle(document.getElementById('wpbody-content')||document.body).overflow};})()

